-- FOCUS_FN database roles and grants (P23), generated by focus.migrations.grants_script from ROLE_GRANTS.
-- PROPOSED, NOT executed by this build. A DBA applies it after migrations 001-009 and then adds members, for example
-- ALTER ROLE FOCUS_FN_AppReader ADD MEMBER [<app user>]. The app login is never a member of a source, stager, signer,
-- evaluator or retention role. The installer is a DBA principal with DDL rights; no script grants DDL. Idempotent.
SET XACT_ABORT ON;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_AppCommand') IS NULL CREATE ROLE FOCUS_FN_AppCommand;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_AppReader') IS NULL CREATE ROLE FOCUS_FN_AppReader;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_Evaluator') IS NULL CREATE ROLE FOCUS_FN_Evaluator;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_ObservationProducer') IS NULL CREATE ROLE FOCUS_FN_ObservationProducer;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_PipelineWorker') IS NULL CREATE ROLE FOCUS_FN_PipelineWorker;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_Retention') IS NULL CREATE ROLE FOCUS_FN_Retention;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_Signer') IS NULL CREATE ROLE FOCUS_FN_Signer;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_SourceWorker') IS NULL CREATE ROLE FOCUS_FN_SourceWorker;
IF DATABASE_PRINCIPAL_ID(N'FOCUS_FN_Stager') IS NULL CREATE ROLE FOCUS_FN_Stager;
GRANT INSERT ON WEB_APP.FOCUS_FN_WorkerRun TO FOCUS_FN_AppCommand;
